<?php
if($page==='login'||$page==='register'){
  if(current_user())go(['page'=>'dashboard']);layout_start($page==='login'?'Sign in':'Create account');?>
  <section class="auth-shell container"><div class="auth-copy"><span class="eyebrow">Travel lighter</span><h1><?=$page==='login'?'Welcome back.':'Store your bags. Keep your day.'?></h1><p>Reserve luggage storage in a few clicks and keep every booking in one place.</p></div><div class="panel auth-panel"><h2><?=$page==='login'?'Sign in':'Create your account'?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="<?=$page==='login'?'login':'register'?>"><?php if($page==='register'):?><label>Full name<input name="name" autocomplete="name" required></label><?php endif;?><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" autocomplete="<?=$page==='login'?'current-password':'new-password'?>" minlength="<?=$page==='login'?'1':'8'?>" required></label><button class="btn btn-block" type="submit"><?=$page==='login'?'Sign in':'Create account'?></button></form><p class="muted"><?=$page==='login'?'New here?':'Already registered.'?> <a href="<?=e(app_url(['page'=>$page==='login'?'register':'login']))?>"><?=$page==='login'?'Create an account':'Sign in'?></a></p></div></section>
  <?php layout_end();exit;
}
